export function getAlternativeCover(
  game: { id?: string; title?: string; coverUrl?: string },
  currentUrl?: string
): string | undefined {
  const norm = game.title ? normalizeGameKey(game.title) : "";
  const candidates: string[] = [];

  if (game.id && ALTERNATIVE_GAME_COVERS[game.id]) {
    candidates.push(...ALTERNATIVE_GAME_COVERS[game.id]);
  }
  if (norm && ALTERNATIVE_GAME_COVERS[norm]) {
    candidates.push(...ALTERNATIVE_GAME_COVERS[norm]);
  }

  // Also check if REAL_GAME_COVERS has an alternate key
  if (game.id && REAL_GAME_COVERS[game.id] && REAL_GAME_COVERS[game.id] !== currentUrl) {
    candidates.push(REAL_GAME_COVERS[game.id]);
  }
  if (norm && REAL_GAME_COVERS[norm] && REAL_GAME_COVERS[norm] !== currentUrl) {
    candidates.push(REAL_GAME_COVERS[norm]);
  }

  // Filter out the current active URL to provide a genuine replacement
  const filtered = candidates.filter((url) => Boolean(url) && url !== currentUrl);
  if (filtered.length > 0) {
    return filtered[0];
  }

  return undefined;
}
